// Common former/colloquial names people still search by, mapped to the name
// actually used in the dataset.
const CITY_ALIASES: Record<string, string> = {
  bengaluru: 'bangalore',
  bombay: 'mumbai',
  madras: 'chennai',
  calcutta: 'kolkata',
  poona: 'pune',
  cochin: 'kochi',
  mysore: 'mysuru',
  baroda: 'vadodara',
  gurgaon: 'gurugram',
  trivandrum: 'thiruvananthapuram',
  vizag: 'visakhapatnam',
  allahabad: 'prayagraj',
  pondicherry: 'puducherry',
};

// `priorityCity` (the user's current device-detected city, if known) pulls
// matches in that city to the top — otherwise a search like "Bell" surfaces
// alphabetically-first areas from anywhere in India ("Bellad Bagewadi,
// Belagavi") ahead of the one the user is actually standing in.
export function searchCities(query: string, priorityCity?: string): string[] {
  const raw = query.trim().toLowerCase();
  if (!raw) return [];
  const q = CITY_ALIASES[raw] || raw;

  // Area-name matches ("Koramangala" -> "Koramangala, Bangalore") rank first,
  // then city-name matches ("Bangalore"/"Bangalore" -> every area in that city) —
  // otherwise searching just a city name would turn up nothing, since no entry's
  // full label actually starts with the city (it's always the second half).
  const areaMatches = INDIA_LOCATIONS.filter(c => c.toLowerCase().startsWith(q));
  const cityMatches = INDIA_LOCATIONS.filter(c => {
    const commaIdx = c.indexOf(', ');
    return commaIdx !== -1 && c.slice(commaIdx + 2).toLowerCase().startsWith(q);
  });

  const seen = new Set<string>();
  const ordered: string[] = [];
  for (const c of [...areaMatches, ...cityMatches]) {
    const key = c.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    ordered.push(c);
  }

  if (priorityCity) {
    const pc = priorityCity.trim().toLowerCase();
    const normalizedPriority = CITY_ALIASES[pc] || pc;
    const suffix = `, ${normalizedPriority}`;
    // Stable sort — only reorders local-city matches ahead of everything
    // else, preserving the area-then-city rank within each group.
    ordered.sort((a, b) => {
      const aLocal = a.toLowerCase().endsWith(suffix) ? 0 : 1;
      const bLocal = b.toLowerCase().endsWith(suffix) ? 0 : 1;
      return aLocal - bLocal;
    });
  }

  return ordered.slice(0, 8);
}

export function isValidCity(name: string): boolean {
  return INDIA_LOCATIONS.some(c => c.toLowerCase() === name.toLowerCase());
}
